import re
from datetime import datetime

# Month name → number mapping (full and abbreviated)
_MONTH_NAMES = {
    "january": 1, "february": 2, "march": 3, "april": 4,
    "may": 5, "june": 6, "july": 7, "august": 8,
    "september": 9, "october": 10, "november": 11, "december": 12,
    "jan": 1, "feb": 2, "mar": 3, "apr": 4,
    "jun": 6, "jul": 7, "aug": 8,
    "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}

# strptime format strings to try in order
_FORMATS = [
    # ISO / numeric with various separators
    "%Y-%m-%d",
    "%Y/%m/%d",
    "%Y.%m.%d",
    "%Y %m %d",
    # US style  mm/dd/yyyy
    "%m/%d/%Y",
    "%m-%d-%Y",
    "%m.%d.%Y",
    "%m %d %Y",
    # day first  dd/mm/yyyy  — tried AFTER US style; ambiguous cases resolved
    # by position (US style wins when both are valid)
    "%d/%m/%Y",
    "%d-%m-%Y",
    "%d.%m.%Y",
    # Long month name
    "%B %d, %Y",
    "%B %d %Y",
    "%d %B %Y",
    "%d %B, %Y",
    # Abbreviated month name
    "%b %d, %Y",
    "%b %d %Y",
    "%d %b %Y",
    "%d %b, %Y",
    # With time components (ignored)
    "%Y-%m-%dT%H:%M:%S",
    "%Y-%m-%d %H:%M:%S",
    "%Y-%m-%dT%H:%M:%SZ",
    # Two-digit year (strptime uses 2000+yy for yy <= 68)
    "%m/%d/%y",
    "%d/%m/%y",
    "%y-%m-%d",
    "%y/%m/%d",
    # Ordinal suffixes stripped later
]


def _strip_ordinal(s: str) -> str:
    """Remove ordinal suffixes: 1st → 1, 2nd → 2, 3rd → 3, 4th → 4, etc."""
    return re.sub(r'(\d+)(st|nd|rd|th)\b', r'\1', s, flags=re.IGNORECASE)


def parse_date(s: str) -> tuple[int, int, int]:
    """Parse a date string and return (year, month, day)."""
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s)}")

    original = s
    s = s.strip()

    if not s:
        raise ValueError("Empty string cannot be parsed as a date")

    # Remove ordinal suffixes (e.g. "March 1st, 2024")
    s_clean = _strip_ordinal(s)

    # Try all strptime formats
    for fmt in _FORMATS:
        for candidate in (s_clean, s_clean.title()):
            try:
                dt = datetime.strptime(candidate.strip(), fmt)
                return (dt.year, dt.month, dt.day)
            except ValueError:
                pass

    # Fallback: attempt a flexible regex-based parse for patterns like
    # "15-Mar-2024", "2024 March 15", "March/15/2024", etc.
    # Normalize separators to spaces
    normalized = re.sub(r'[\s,/.\-]+', ' ', s_clean).strip()
    parts = normalized.split()

    if len(parts) == 3:
        year, month, day = _guess_ymd(parts)
        if year is not None:
            return (year, month, day)

    raise ValueError(f"Cannot parse date string: {original!r}")


def _to_month_num(token: str) -> int | None:
    """Convert a token to a month number, or None if not recognizable."""
    lower = token.lower()
    if lower in _MONTH_NAMES:
        return _MONTH_NAMES[lower]
    # Try as integer
    try:
        m = int(token)
        if 1 <= m <= 12:
            return m
    except ValueError:
        pass
    return None


def _guess_ymd(parts: list[str]) -> tuple[int | None, int | None, int | None]:
    """
    Given exactly 3 string parts, try to figure out which is year, month, day.
    Returns (year, month, day) integers or (None, None, None) on failure.
    """
    # Identify which parts are pure integers
    int_vals = []
    for p in parts:
        try:
            int_vals.append(int(p))
        except ValueError:
            int_vals.append(None)

    # Check if any part is a month name
    month_indices = []
    for i, p in enumerate(parts):
        if p.lower() in _MONTH_NAMES:
            month_indices.append(i)

    if len(month_indices) == 1:
        mi = month_indices[0]
        month = _MONTH_NAMES[parts[mi].lower()]
        remaining = [(i, int_vals[i]) for i in range(3) if i != mi]
        # remaining should be two integers
        if all(v is not None for _, v in remaining):
            a_idx, a = remaining[0]
            b_idx, b = remaining[1]
            # Determine which is year vs day
            # Year is typically 4 digits or > 31
            if a > 31 or (a >= 100):
                return (a, month, b)
            elif b > 31 or (b >= 100):
                return (b, month, a)
            else:
                # Ambiguous: assume first non-month is day if ≤31 else year
                # Convention: larger number = year
                if a > b:
                    return (a, month, b)
                else:
                    return (b, month, a)
        return (None, None, None)

    # All three are integers (or should be)
    if all(v is not None for v in int_vals):
        a, b, c = int_vals

        # If one value is clearly a year (>= 1000 or > 31)
        if a >= 1000:
            # Year-first: a=year, then figure out month/day
            # b is month if 1<=b<=12, c is day
            if 1 <= b <= 12 and 1 <= c <= 31:
                return (a, b, c)
            elif 1 <= c <= 12 and 1 <= b <= 31:
                return (a, c, b)
        elif c >= 1000:
            # Year-last
            if 1 <= a <= 12 and 1 <= b <= 31:
                return (c, a, b)
            elif 1 <= b <= 12 and 1 <= a <= 31:
                return (c, b, a)
        # Two-digit year or purely ambiguous — skip
        return (None, None, None)

    return (None, None, None)

